    DateTimeFormattingType? formattingType,
    dynamic extra,
    int? clientId,
  }) => TextEntityTypeDateTime(
    unixTime: unixTime ?? this.unixTime,
    formattingType: formattingType ?? this.formattingType,
    extra: extra ?? this.extra,
    clientId: clientId ?? this.clientId,
  );
}
